#include <memory>
#include <iostream>

struct Resource { 
    ~Resource() { std::cout << "Resource Deleted\n"; }
};

void dangerous_usage() {
    Resource* raw_ptr = new Resource();

    // auto_ptr A owns the resource
    std::auto_ptr<Resource> ptrA(raw_ptr);

    // DANGER! auto_ptr B also owns the resource
    // Both will attempt deletion upon scope exit
    std::auto_ptr<Resource> ptrB(raw_ptr);

    // Result: Double deletion (Undefined Behavior)
}
